import { test } from 'node:test';
import assert from 'node:assert';

import { createDatabase, createMysqlDriver, createPgDriver, DbConfigError, defineModel } from '../src/index.ts';

/**
 * 自增整数主键（用户要求）。
 *
 * 这是**身份策略**而不是列类型，三方言写法差别很大，而且 insert 之后必须**回读**生成值：
 *   - PostgreSQL：`GENERATED BY DEFAULT AS IDENTITY` + `INSERT … RETURNING`
 *   - MySQL：`AUTO_INCREMENT` + 结果里的 `insertId`（MySQL 没有 RETURNING）
 *   - SQLite：`INTEGER PRIMARY KEY AUTOINCREMENT` + `RETURNING`（或 rowid）
 */
const Note = defineModel({
  name: 'notes',
  fields: {
    id: { type: 'integer', primaryKey: true, autoIncrement: true },
    title: { type: 'string', length: 200, notNull: true },
  },
});

test('autoIncrement: DDL 三方言逐条对照（身份策略不同，不能假装一样）', () => {
  const sqlite = Note.createTableSql('sqlite');
  assert.match(
    sqlite,
    /"id" integer PRIMARY KEY AUTOINCREMENT/,
    `sqlite 必须是 INTEGER PRIMARY KEY AUTOINCREMENT（rowid 别名）：${sqlite}`,
  );

  const pg = Note.createTableSql('pgsql');
  assert.match(pg, /"id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY/, `pg DDL 不对：${pg}`);
  // BY DEFAULT（不是 ALWAYS）：显式给 id 的插入仍然允许
  assert.ok(!pg.includes('GENERATED ALWAYS'), 'pg 不该用 GENERATED ALWAYS（会让显式 id 插不进去）');

  const mysql = Note.createTableSql('mysql');
  assert.match(mysql, /`id` int NOT NULL AUTO_INCREMENT PRIMARY KEY/, `mysql DDL 不对：${mysql}`);

  // bigint 也要支持
  const Big = defineModel({
    name: 'events',
    fields: { id: { type: 'bigint', primaryKey: true, autoIncrement: true } },
  });
  assert.match(Big.createTableSql('pgsql'), /"id" bigint GENERATED BY DEFAULT AS IDENTITY/);
  assert.match(Big.createTableSql('mysql'), /`id` bigint NOT NULL AUTO_INCREMENT/);
  assert.match(Big.createTableSql('sqlite'), /"id" integer PRIMARY KEY AUTOINCREMENT/);
});

test('autoIncrement: 配置校验 —— 只能用在整数类型上，且必须是主键', () => {
  assert.throws(
    () => defineModel({ name: 'x', fields: { id: { type: 'uuid', primaryKey: true, autoIncrement: true } } }),
    (err: Error) => {
      assert.ok(err instanceof DbConfigError);
      assert.match(err.message, /autoIncrement/i);
      assert.match(err.message, /integer|bigint|smallint|tinyint/i);
      return true;
    },
  );
  assert.throws(
    () =>
      defineModel({
        name: 'x',
        fields: {
          id: { type: 'string', primaryKey: true },
          n: { type: 'integer', autoIncrement: true }, // 不是主键
        },
      }),
    /autoIncrement.*primary key/i,
  );
});

test('autoIncrement/sqlite: insert 不写 id，并回读生成值（连续插入自增）', async () => {
  const db = createDatabase({ dialect: 'sqlite', connection: { filename: ':memory:' } });
  await db.connect();
  try {
    await db.sync([Note]);
    const notes = db.repository(Note);

    const first = await notes.insert({ title: 'first' });
    assert.strictEqual(typeof first.id, 'number', `sqlite 回读的 id 应当是 number，实际 ${String(first.id)}`);
    const second = await notes.insert({ title: 'second' });
    assert.strictEqual(Number(second.id), Number(first.id) + 1, '自增没有生效');

    assert.strictEqual((await notes.findById(first.id))?.title, 'first');
    assert.strictEqual((await notes.findById(second.id))?.title, 'second');

    // 显式给 id 的插入仍然允许（AUTOINCREMENT 的语义）
    const explicit = await notes.insert({ id: 100, title: 'explicit' } as never);
    assert.strictEqual(explicit.id, 100);
    assert.strictEqual((await notes.findById(100))?.title, 'explicit');
  } finally {
    await db.close();
  }
});

test('autoIncrement: 假驱动验证 pg 走 RETURNING、mysql 走 insertId', async () => {
  // ---- pg：INSERT 必须带 RETURNING，返回值从结果行里取
  const pgCalls: Array<{ sql: string; params: unknown[] }> = [];
  class FakePgPool {
    async query(sql: string, params: unknown[] = []) {
      pgCalls.push({ sql, params });
      if (/from information_schema\.tables/i.test(sql)) return { rows: [], rowCount: 0 };
      if (/^select/i.test(sql.trim())) return { rows: [{ id: 7, title: 'x' }], rowCount: 1 };
      return { rows: [{ id: 7 }], rowCount: 1 };
    }
    async connect() {
      return this;
    }
    async end() {}
  }
  const pgDb = createDatabase({
    dialect: 'pgsql',
    connection: { host: 'h', database: 'd' },
    driver: createPgDriver(async () => ({ Pool: FakePgPool })),
  });
  await pgDb.connect();
  try {
    const created = await pgDb.repository(Note).insert({ title: 'x' });
    const insert = pgCalls.find((call) => /^insert into/i.test(call.sql.trim()));
    assert.ok(insert, '没有发出 INSERT');
    assert.match(insert.sql, /RETURNING "id"/i, `pg 的 INSERT 必须带 RETURNING：${insert.sql}`);
    assert.ok(!/"id"/.test(insert.sql.split('(')[1] ?? ''), '自动生成 id 时不该显式写 id 列');
    assert.strictEqual(created.id, 7, 'pg 没有把 RETURNING 的 id 回填进实体');
  } finally {
    await pgDb.close();
  }

  // ---- mysql：没有 RETURNING，必须用 insertId
  const mysqlCalls: string[] = [];
  const pool = {
    async query(sql: string, _params: unknown[] = []) {
      mysqlCalls.push(sql);
      if (/from information_schema\.tables/i.test(sql)) return [[], []];
      if (/^insert/i.test(sql.trim())) return [{ affectedRows: 1, insertId: 42 }, []];
      return [[], []];
    },
    async getConnection() {
      return this;
    },
    async end() {},
  };
  const mysqlDb = createDatabase({
    dialect: 'mysql',
    connection: { host: 'h', database: 'd' },
    driver: createMysqlDriver(async () => ({ createPool: () => pool })),
  });
  await mysqlDb.connect();
  try {
    const created = await mysqlDb.repository(Note).insert({ title: 'x' });
    const insert = mysqlCalls.find((sql) => /^insert/i.test(sql.trim()));
    assert.ok(insert);
    assert.ok(!/returning/i.test(insert), `mysql 不支持 RETURNING，不该出现它：${insert}`);
    assert.strictEqual(created.id, 42, 'mysql 没有把 insertId 回填进实体');
  } finally {
    await mysqlDb.close();
  }
});

test('autoIncrement/sqlite: 重复 sync 幂等、漂移报告干净（身份列不会被误判）', async () => {
  const db = createDatabase({ dialect: 'sqlite', connection: { filename: ':memory:' } });
  await db.connect();
  try {
    assert.deepStrictEqual((await db.sync([Note])).created, ['notes']);
    assert.deepStrictEqual((await db.sync([Note])).created, [], '第二次 sync 不该再建表');
    assert.strictEqual((await db.checkDrift(Note)).ok, true, '自增列被误判成漂移了');
    // 内省出来的类型也要对得上（sqlite 报 integer）
    const info = await db.inspectTable('notes');
    assert.strictEqual(info.columns.find((c) => c.name === 'id')?.type, 'integer');
  } finally {
    await db.close();
  }
});
